      "content": "const crypto = require('node:crypto')\nconst session = require('express-session')\n\nconst COOKIE_NAME = 'stylesync.sid'\nconst IDLE_MS = 30 * 60 * 1000\nconst ABSOLUTE_MS = 8 * 60 * 60 * 1000\nconst ADMIN_ROLES = ['owner', 'admin']\nconst ROLES = [...ADMIN_ROLES, 'user']\n\nfunction cookieOptions(production) {\n  return { httpOnly: true, secure: production, sameSite: 'lax', path: '/' }\n}\n\nfunction createSessionMiddleware({ store, secret, production = false }) {\n  if (!secret || Buffer.byteLength(secret) < 32 || secret.includes('replace_with')) {\n    throw new Error('Set SESSION_SECRET to a randomly generated secret of at least 32 bytes.')\n  }\n  return session({\n    name: COOKIE_NAME, secret, store, resave: false, saveUninitialized: false,\n    rolling: true,\n    cookie: { ...cookieOptions(production), maxAge: IDLE_MS },\n  })\n}\n\nfunction csrfToken(req) {\n  if (!req.session.csrfToken) req.session.csrfToken = crypto.randomBytes(32).toString('hex')\n  return req.session.csrfToken\n}\n\nfunction requireCsrf(req, res, next) {\n  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) return next()\n  const actual = req.get('X-CSRF-Token') || ''\n  const expected = req.session?.csrfToken || ''\n  const actualBytes = Buffer.from(actual)\n  const expectedBytes = Buffer.from(expected)\n  if (!expected || actualBytes.length !== expectedBytes.length ||\n      !crypto.timingSafeEqual(actualBytes, expectedBytes)) {\n    return res.status(403).json({ error: 'Your security token expired. Refresh the page and try again.', code: 'CSRF_INVALID' })\n  }\n  next()\n}\n\nfunction publicUser(user) {\n  return { user_id: user.user_id, username: user.username, email: user.email, role: user.role }\n}\n\nfunction sessionPayload(req) {\n  const now = Date.now()\n  return {\n    user: req.user || null,\n    csrfToken: csrfToken(req),\n    expiresAt: req.user ? Math.min(now + IDLE_MS, req.session.authenticatedAt + ABSOLUTE_MS) : null,\n  }\n}\n\nfunction destroySession(req, res) {\n  return new Promise((resolve, reject) => {\n    req.session.destroy((err) => {\n      if (err) return reject(err)\n      res.clearCookie(COOKIE_NAME, cookieOptions(req.app.get('env') === 'production'))\n      resolve()\n    })\n  })\n}\n\nfunction loadUser(database) {\n  return async (req, res, next) => {\n    if (!req.session.userId) return next()\n    if (!Number.isFinite(req.session.authenticatedAt) || Date.now() - req.session.authenticatedAt >= ABSOLUTE_MS) {\n      await destroySession(req, res)\n      return res.status(401).json({ error: 'Your session expired. Please log in again.' })\n    }\n    const [rows] = await database.query(\n      'SELECT user_id, username, email, role FROM users WHERE user_id = ? LIMIT 1',\n      [req.session.userId]\n    )\n    if (!rows.length || !ROLES.includes(rows[0].role)) {\n      await destroySession(req, res)\n      return res.status(401).json({ error: 'Your account is no longer available. Please log in again.' })\n    }\n    // Authorization always comes from the database, never from request bodies or browser storage.\n    req.user = publicUser(rows[0])\n    res.set('X-Session-Expires', String(Math.min(Date.now() + IDLE_MS, req.session.authenticatedAt + ABSOLUTE_MS)))\n    next()\n  }\n}\n\nfunction requireUser(req, res, next) {\n  if (!req.user) return res.status(401).json({ error: 'Please log in to continue.' })\n  next()\n}\nfunction requireRoles(...roles) {\n  return (req, res, next) => requireUser(req, res, () => {\n    if (!roles.includes(req.user.role)) return res.status(403).json({ error: 'You do not have permission to access this page.' })\n    next()\n  })\n}\nconst requireAdmin = requireRoles(...ADMIN_ROLES)\nconst requireOwner = requireRoles('owner')\n\nmodule.exports = { COOKIE_NAME, IDLE_MS, ABSOLUTE_MS, ADMIN_ROLES, createSessionMiddleware,\n  csrfToken, requireCsrf, publicUser, sessionPayload, destroySession, loadUser,\n  requireUser, requireAdmin, requireOwner }\n"
