      "content": "const express = require('express')\nconst cors = require('cors')\nconst path = require('node:path')\nconst fs = require('node:fs')\nconst { createSessionMiddleware, requireCsrf, loadUser, requireUser, requireAdmin } = require('./auth')\nconst createAuthRouter = require('./routes/authRoutes')\n\nfunction createApp({ database, sessionStore, secret, production = false, allowedOrigins = [], trustProxy = false, routes }) {\n  const app = express()\n  app.set('env', production ? 'production' : 'development')\n  app.disable('x-powered-by')\n  if (trustProxy) app.set('trust proxy', 1)\n  const api = express.Router()\n  api.use((req, res, next) => {\n    res.set('Cache-Control', 'no-store')\n    res.set('X-Content-Type-Options', 'nosniff')\n    const origin = req.get('Origin')\n    if (origin && !allowedOrigins.includes(origin)) {\n      return res.status(403).json({ error: 'This website is not allowed to access the API.' })\n    }\n    next()\n  })\n  api.use(cors({ origin: allowedOrigins, credentials: true, exposedHeaders: ['X-Session-Expires'] }))\n  api.use(express.json({ limit: '1mb' }))\n  api.use(createSessionMiddleware({ store: sessionStore, secret, production }))\n  api.use(loadUser(database))\n  api.use(requireCsrf)\n  api.use('/auth', createAuthRouter(database))\n  api.use(requireUser)\n\n  // Apply guards before entering any existing business route or upload handler.\n  api.use('/services', (req, res, next) => ['GET', 'HEAD'].includes(req.method) ? next() : requireAdmin(req, res, next), routes.services)\n  api.use('/appointments', (req, res, next) => {\n    const customerRead = ['GET', 'HEAD'].includes(req.method) && req.path.replace(/\\/$/, '') === '/availability'\n    const customerBooking = req.method === 'POST' && req.path === '/' && !req.body?.offline_id\n    if (customerRead || customerBooking) return next()\n    return requireAdmin(req, res, next)\n  }, routes.appointments)\n  for (const name of ['staff', 'inventory', 'transactions', 'recommendations', 'dashboard', 'reports', 'forecast', 'gad']) {\n    if (routes[name]) api.use(`/${name}`, requireAdmin, routes[name])\n  }\n  api.use((req, res) => res.status(404).json({ error: 'API endpoint not found.' }))\n  app.use('/api', api)\n  app.use('/uploads', express.static(path.join(__dirname, 'uploads')))\n  app.use('/uploads', express.static(path.join(__dirname, '../uploads')))\n  const client = path.join(__dirname, '../client/dist')\n  if (fs.existsSync(path.join(client, 'index.html'))) {\n    app.use(express.static(client, { index: false }))\n    app.get('/{*path}', (req, res) => {\n      res.set('Cache-Control', 'no-store')\n      res.sendFile(path.join(client, 'index.html'))\n    })\n  } else {\n    app.get('/', (req, res) => res.redirect(302, `${allowedOrigins[0] || 'http://localhost:5173'}/login`))\n  }\n  app.use((err, req, res, next) => {\n    if (res.headersSent) return next(err)\n    console.error('Request failed:', err.code || err.name)\n    res.status(err.status === 400 ? 400 : 500).json({ error: err.status === 400 ? 'Invalid request.' : 'Unable to complete the request. Please try again.' })\n  })\n  return app\n}\nmodule.exports = createApp\n"
