      "content": "const express = require('express')\nconst bcrypt = require('bcrypt')\nconst { rateLimit } = require('express-rate-limit')\nconst { requireUser, requireOwner, sessionPayload, destroySession, publicUser } = require('../auth')\n\nfunction credentials(body = {}, registration = false, emailRequired = true) {\n  const username = typeof body.username === 'string' ? body.username.trim() : ''\n  const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : ''\n  const password = typeof body.password === 'string' ? body.password : ''\n  if (registration) {\n    if (!/^[A-Za-z0-9_.-]{3,50}$/.test(username)) {\n      return { error: 'Username must be 3–50 letters, numbers, dots, underscores, or hyphens.' }\n    }\n    if ((emailRequired || email) && (email.length > 254 || !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email))) {\n      return { error: 'Enter a valid email address.' }\n    }\n    if (password.length < 8 || Buffer.byteLength(password) > 72) {\n      return { error: 'Password must contain at least 8 characters and at most 72 bytes.' }\n    }\n  }\n  return { username, email: email || null, password }\n}\n\nfunction createAuthRouter(database) {\n  const router = express.Router()\n  const loginLimit = rateLimit({ windowMs: 15 * 60 * 1000, limit: 20, standardHeaders: 'draft-8', legacyHeaders: false,\n    skipSuccessfulRequests: true, message: { error: 'Too many login attempts. Please try again in 15 minutes.' } })\n  const signupLimit = rateLimit({ windowMs: 60 * 60 * 1000, limit: 10, standardHeaders: 'draft-8', legacyHeaders: false,\n    message: { error: 'Too many account creation attempts. Please try again later.' } })\n  const dummyHash = bcrypt.hashSync('invalid-login-placeholder', 12)\n\n  router.get('/session', (req, res) => res.json(sessionPayload(req)))\n\n  router.post('/login', loginLimit, async (req, res) => {\n    const body = req.body || {}\n    const identifier = typeof (body.identifier ?? body.username) === 'string' ? (body.identifier ?? body.username).trim() : ''\n    const password = typeof body.password === 'string' ? body.password : ''\n    if (!identifier || identifier.length > 254 || !password || Buffer.byteLength(password) > 72) {\n      return res.status(400).json({ error: 'Enter your username or email and password.' })\n    }\n    const [rows] = await database.query(\n      'SELECT user_id, username, email, password, role FROM users WHERE LOWER(username) = ? OR LOWER(email) = ? LIMIT 2',\n      [identifier.toLowerCase(), identifier.toLowerCase()]\n    )\n    const user = rows.length === 1 ? rows[0] : null\n    const matches = await bcrypt.compare(password, user?.password || dummyHash)\n    if (!user || !matches || !['owner', 'admin', 'user'].includes(user.role)) {\n      return res.status(401).json({ error: 'Incorrect username/email or password.' })\n    }\n    await new Promise((resolve, reject) => req.session.regenerate(err => err ? reject(err) : resolve()))\n    req.session.userId = user.user_id\n    req.session.authenticatedAt = Date.now()\n    req.user = publicUser(user)\n    const payload = sessionPayload(req)\n    await new Promise((resolve, reject) => req.session.save(err => err ? reject(err) : resolve()))\n    res.json({ ...payload, message: 'Login successful', redirectTo: user.role === 'user' ? '/dashboard' : '/admin' })\n  })\n\n  async function createAccount(req, res, managed = false) {\n    const values = credentials(req.body, true, !managed)\n    if (values.error) return res.status(400).json({ error: values.error })\n    const role = managed ? req.body.role : 'user'\n    if (!['user', 'admin', 'owner'].includes(role)) return res.status(400).json({ error: 'Invalid account role.' })\n    const [existing] = await database.query(\n      'SELECT user_id FROM users WHERE LOWER(username) = ? OR LOWER(email) = ? LIMIT 1',\n      [values.username.toLowerCase(), values.email]\n    )\n    if (existing.length) return res.status(409).json({ error: 'That username or email is already registered.' })\n    const hash = await bcrypt.hash(values.password, 12)\n    try {\n      const [result] = await database.query('INSERT INTO users (username, email, password, role) VALUES (?, ?, ?, ?)',\n        [values.username, values.email, hash, role])\n      res.status(201).json({ message: managed ? 'Account created successfully.' : 'Account created. Please log in.', user_id: result.insertId })\n    } catch (err) {\n      if (err.code === 'ER_DUP_ENTRY') return res.status(409).json({ error: 'That username or email is already registered.' })\n      throw err\n    }\n  }\n\n  // Both public registration URLs always create regular users, regardless of submitted role fields.\n  router.post(['/signup', '/register'], signupLimit, (req, res) => createAccount(req, res))\n  router.post('/logout', async (req, res) => {\n    await destroySession(req, res)\n    res.json({ message: 'Logged out successfully.' })\n  })\n  router.get('/me', requireUser, (req, res) => res.json(sessionPayload(req)))\n  router.get('/users', requireOwner, async (req, res) => {\n    const [rows] = await database.query('SELECT user_id, username, email, role, created_at FROM users ORDER BY created_at DESC')\n    res.json(rows)\n  })\n  router.post('/users', requireOwner, (req, res) => createAccount(req, res, true))\n  router.delete('/users/:id', requireOwner, async (req, res) => {\n    const id = Number(req.params.id)\n    if (!Number.isSafeInteger(id) || id < 1) return res.status(400).json({ error: 'Invalid account.' })\n    if (id === req.user.user_id) return res.status(400).json({ error: 'You cannot delete your own account.' })\n    const [result] = await database.query('DELETE FROM users WHERE user_id = ?', [id])\n    res.json({ message: 'Account deleted successfully.', affectedRows: result.affectedRows })\n  })\n  return router\n}\nmodule.exports = createAuthRouter\nmodule.exports.credentials = credentials\n"
