      "content": "require('./loadEnv')\nconst session = require('express-session')\nconst MySQLStore = require('express-mysql-session')(session)\nconst db = require('./db')\nconst createApp = require('./app')\n\nconst routes = {\n  services: require('./routes/serviceRoutes'),\n  appointments: require('./routes/appointments'),\n  staff: require('./routes/staffRoutes'),\n  inventory: require('./routes/inventoryRoutes'),\n  transactions: require('./routes/transactionRoutes'),\n  recommendations: require('./routes/recommendationRoutes'),\n  dashboard: require('./routes/dashboardRoutes'),\n  reports: require('./routes/reportRoutes'),\n  forecast: require('./routes/forecastRoutes'),\n  gad: require('./routes/gadRoutes'),\n}\n\nasync function start() {\n  const database = db.promise()\n  // Fail before listening when the migration or database connection is missing.\n  await database.query('SELECT user_id, username, email, password, role FROM users LIMIT 0')\n  await database.query('SELECT session_id, expires, data FROM auth_sessions LIMIT 0')\n  const sessionStore = new MySQLStore({ createDatabaseTable: false, schema: { tableName: 'auth_sessions' } }, database)\n  const app = createApp({ database, sessionStore, routes,\n    secret: process.env.SESSION_SECRET,\n    production: process.env.NODE_ENV === 'production',\n    trustProxy: process.env.TRUST_PROXY === '1',\n    allowedOrigins: (process.env.CLIENT_ORIGINS || 'http://localhost:5173,http://127.0.0.1:5173,http://localhost:5000,http://127.0.0.1:5000').split(',').map(value => value.trim()).filter(Boolean),\n  })\n  const server = app.listen(Number(process.env.PORT || 5000), '0.0.0.0', () => console.log(`StyleSync running on port ${server.address().port}`))\n  for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, () => server.close(async () => {\n    await sessionStore.close()\n    await database.end()\n    process.exit(0)\n  }))\n}\nstart().catch(error => {\n  console.error('Startup failed. Check .env and run npm run migrate:auth.', error.message)\n  process.exit(1)\n})\n"
