      "content": "require('../loadEnv')\n\nasync function migrate(connection) {\n  const [columns] = await connection.query('SHOW COLUMNS FROM users')\n  for (const required of ['user_id', 'username', 'password', 'role']) {\n    if (!columns.some(column => column.Field === required)) throw new Error(`users.${required} is missing; check the existing schema first.`)\n  }\n  const [duplicates] = await connection.query('SELECT LOWER(TRIM(username)) AS name, COUNT(*) AS total FROM users GROUP BY LOWER(TRIM(username)) HAVING COUNT(*) > 1')\n  if (duplicates.length) throw new Error('Duplicate usernames exist after case normalization. Resolve them before migrating.')\n  const [roles] = await connection.query(\"SELECT DISTINCT role FROM users WHERE role IS NULL OR LOWER(TRIM(role)) NOT IN ('owner', 'admin', 'user')\")\n  if (roles.length) throw new Error('Unknown user roles exist. Map them to owner, admin, or user before migrating.')\n  if (!columns.some(column => column.Field === 'email')) {\n    await connection.query('ALTER TABLE users ADD COLUMN email VARCHAR(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL AFTER username')\n  }\n  await connection.query(\"UPDATE users SET email = NULL WHERE TRIM(email) = ''\")\n  const [emailDuplicates] = await connection.query('SELECT LOWER(TRIM(email)) FROM users WHERE email IS NOT NULL GROUP BY LOWER(TRIM(email)) HAVING COUNT(*) > 1')\n  if (emailDuplicates.length) throw new Error('Duplicate emails exist. Resolve them before migrating.')\n  const [collisions] = await connection.query('SELECT a.user_id FROM users a JOIN users b ON LOWER(TRIM(a.username)) = LOWER(TRIM(b.email)) WHERE a.user_id <> b.user_id LIMIT 1')\n  if (collisions.length) throw new Error('A username matches another account email. Resolve this ambiguous login before migrating.')\n  await connection.query('UPDATE users SET email = LOWER(TRIM(email)), role = LOWER(TRIM(role))')\n  await connection.query('ALTER TABLE users MODIFY email VARCHAR(254) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL')\n  await connection.query(\"ALTER TABLE users MODIFY role VARCHAR(50) NOT NULL DEFAULT 'user'\")\n  if (!columns.some(column => column.Field === 'auth_username_key')) {\n    await connection.query('ALTER TABLE users ADD COLUMN auth_username_key VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (LOWER(TRIM(username))) STORED')\n  }\n  const [indexes] = await connection.query('SHOW INDEX FROM users')\n  if (!indexes.some(index => index.Key_name === 'uq_auth_username')) await connection.query('CREATE UNIQUE INDEX uq_auth_username ON users (auth_username_key)')\n  if (!indexes.some(index => index.Key_name === 'uq_auth_email')) await connection.query('CREATE UNIQUE INDEX uq_auth_email ON users (email)')\n  await connection.query(`CREATE TABLE IF NOT EXISTS auth_sessions (\n    session_id VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL PRIMARY KEY,\n    expires INT UNSIGNED NOT NULL,\n    data MEDIUMTEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,\n    INDEX ix_auth_session_expiry (expires)\n  ) ENGINE=InnoDB`)\n}\n\nasync function main() {\n  const connection = require('../db').promise()\n  try { await migrate(connection); console.log('Authentication migration complete. Existing accounts and password hashes were preserved.') }\n  finally { await connection.end() }\n}\nif (require.main === module) main().catch(error => { console.error('Migration failed:', error.message); process.exitCode = 1 })\nmodule.exports = migrate\n"
