      "content": "export const API_URL = (import.meta.env.VITE_API_URL || '/api').replace(/\\/$/, '')\nexport const ASSET_URL = API_URL.replace(/\\/api$/, '')\nlet csrf = null\nlet sessionRequest = null\nlet csrfVersion = 0\n\nexport function setCsrfToken(token) { csrf = token || null; csrfVersion++ }\n\nexport async function fetchSession() {\n  if (!sessionRequest) {\n    const version = csrfVersion\n    sessionRequest = fetch(`${API_URL}/auth/session`, { credentials: 'include', cache: 'no-store' })\n      .then(async response => {\n        const data = await response.json()\n        if (!response.ok) {\n          const error = new Error(data.error || 'Unable to verify your session.')\n          error.status = response.status\n          throw error\n        }\n        if (version === csrfVersion) setCsrfToken(data.csrfToken)\n        return data\n      }).finally(() => { sessionRequest = null })\n  }\n  return sessionRequest\n}\n\nexport async function apiFetch(url, options = {}) {\n  const method = (options.method || 'GET').toUpperCase()\n  const headers = new Headers(options.headers)\n  if (!['GET', 'HEAD', 'OPTIONS'].includes(method)) {\n    if (!csrf) await fetchSession()\n    headers.set('X-CSRF-Token', csrf)\n  }\n  const response = await fetch(url, { ...options, headers, credentials: 'include', cache: 'no-store' })\n  const expiry = Number(response.headers.get('X-Session-Expires'))\n  if (expiry) window.dispatchEvent(new CustomEvent('auth-activity', { detail: expiry }))\n  if (response.status === 401 && !url.endsWith('/auth/login')) {\n    setCsrfToken(null)\n    window.dispatchEvent(new Event('auth-expired'))\n  }\n  if (response.status === 403) {\n    const data = await response.clone().json().catch(() => ({}))\n    if (data.code === 'CSRF_INVALID') setCsrfToken(null)\n  }\n  return response\n}\n"
