      "content": "import { Link } from 'react-router-dom'\nimport Navbar from '../components/Navbar'\nimport Footer from '../components/Footer'\nimport { useAuth } from '../auth/AuthContext'\n\nexport default function UserDashboard() {\n  const { user } = useAuth()\n  return <div className=\"min-h-screen bg-pink-50\">\n    <Navbar />\n    <main className=\"max-w-6xl mx-auto px-6 py-16\">\n      <p className=\"font-semibold text-pink-600 mb-2\">Dahling's Salon &amp; Spa</p>\n      <h1 className=\"text-4xl font-bold text-purple-800 mb-4\">User Dashboard</h1>\n      <p className=\"text-gray-600 mb-10\">Welcome, {user.username}. Plan your next salon visit.</p>\n      <div className=\"grid md:grid-cols-3 gap-6\">\n        {[\n          ['/book', 'Book an Appointment', 'Choose a service and an available schedule.'],\n          ['/services', 'Explore Services', 'Browse our salon and spa treatments.'],\n          ['/contact', 'Contact the Salon', 'Find our contact details and opening hours.'],\n        ].map(([to, title, description]) => <Link key={to} to={to} className=\"bg-white rounded-2xl shadow p-8 hover:shadow-lg focus:ring-2 focus:ring-purple-500\">\n          <h2 className=\"text-xl font-bold text-purple-700 mb-3\">{title}</h2>\n          <p className=\"text-gray-600\">{description}</p>\n        </Link>)}\n      </div>\n    </main>\n    <Footer />\n  </div>\n}\n"
