    "server/tests/helpers/authFixture.js": {
      "before": [],
      "content": "// Test-only database and routes. Production always uses MySQL and the real route files.\nconst bcrypt = require('bcrypt')\nconst express = require('express')\nconst session = require('express-session')\nconst createApp = require('../../app')\nconst SECRET = 'test-only-secret-do-not-use-in-production-123456789'\n\nfunction fixture(options = {}) {\n  const password = 'TestingPassword42!'\n  const hash = bcrypt.hashSync(password, 4)\n  const users = [\n    { user_id: 1, username: 'owner', email: 'owner@example.test', role: 'owner', password: hash },\n    { user_id: 2, username: 'admin', email: 'admin@example.test', role: 'admin', password: hash },\n    { user_id: 3, username: 'customer', email: 'customer@example.test', role: 'user', password: hash },\n  ]\n  const database = { async query(sql, args = []) {\n    if (sql.startsWith('SELECT user_id, username, email, role FROM users WHERE')) return [users.filter(u => u.user_id === args[0]).map(({ password, ...u }) => u)]\n    if (sql.startsWith('SELECT user_id, username, email, password, role')) return [users.filter(u => u.username.toLowerCase() === args[0] || u.email?.toLowerCase() === args[1])]\n    if (sql.startsWith('SELECT user_id FROM users')) return [users.filter(u => u.username.toLowerCase() === args[0] || (args[1] && u.email?.toLowerCase() === args[1]))]\n    if (sql.startsWith('INSERT INTO users')) {\n      if (users.some(u => u.username.toLowerCase() === args[0].toLowerCase() || (args[1] && u.email === args[1]))) {\n        const err = new Error('Duplicate'); err.code = 'ER_DUP_ENTRY'; throw err\n      }\n      const user_id = Math.max(0, ...users.map(u => u.user_id)) + 1\n      users.push({ user_id, username: args[0], email: args[1], password: args[2], role: args[3] })\n      return [{ insertId: user_id }]\n    }\n    if (sql.startsWith('SELECT user_id, username, email, role, created_at')) return [users.map(({ password, ...u }) => u)]\n    if (sql.startsWith('DELETE FROM users')) {\n      const index = users.findIndex(u => u.user_id === args[0]); if (index >= 0) users.splice(index, 1)\n      return [{ affectedRows: index >= 0 ? 1 : 0 }]\n    }\n    throw new Error(`Unexpected test SQL: ${sql}`)\n  } }\n  const routes = {}\n  for (const name of ['services', 'appointments', 'staff', 'inventory', 'transactions', 'recommendations', 'dashboard', 'reports', 'forecast', 'gad']) {\n    const router = express.Router()\n    router.use((req, res) => res.json(name === 'dashboard' ? { totalSales: 0, totalAppointments: 0 } : []))\n    routes[name] = router\n  }\n  const store = new session.MemoryStore()\n  const app = createApp({ database, sessionStore: store, secret: SECRET, allowedOrigins: ['http://localhost:5173'], routes, ...options })\n  return { app, store, users, password, database }\n}\n\nasync function client(base) {\n  let cookie = ''\n  let token = ''\n  async function request(path, { method = 'GET', body, csrf = true, headers = {}, cookieOverride } = {}) {\n    const response = await fetch(base + '/api' + path, { method, headers: {\n      ...(cookieOverride ?? cookie ? { Cookie: cookieOverride ?? cookie } : {}),\n      ...(body === undefined ? {} : { 'Content-Type': 'application/json' }),\n      ...(csrf && token ? { 'X-CSRF-Token': token } : {}), ...headers,\n    }, body: body === undefined ? undefined : JSON.stringify(body) })\n    const setCookie = response.headers.get('set-cookie')\n    if (setCookie) cookie = setCookie.split(';')[0]\n    const data = await response.json()\n    if (data.csrfToken) token = data.csrfToken\n    return { status: response.status, data, headers: response.headers }\n  }\n  await request('/auth/session')\n  return { request, get cookie() { return cookie }, get token() { return token } }\n}\nmodule.exports = { fixture, client, SECRET }\n"
    },
