function transform(name, text) {
  let s = normalize(text)
  if (name.endsWith('/Navbar.jsx')) {
    s=s.replace('import { Link } from "react-router-dom"','import { Link } from "react-router-dom"\nimport LogoutButton from "./LogoutButton"\nimport { useAuth, dashboardFor } from "../auth/AuthContext"')
      .replace('function Navbar() {','function Navbar() {\n  const { user } = useAuth()')
      .replace('<Link to="/">Home</Link>','<Link to="/home">Home</Link>')
      .replace('<ul className="flex gap-6 font-medium items-center">','<ul className="flex flex-wrap gap-4 font-medium items-center">\n        <li><Link to={dashboardFor(user)}>Dashboard</Link></li>')
      .replace('</ul>','<li><LogoutButton /></li>\n      </ul>')
  } else if (name.endsWith('/AdminLayout.jsx')) {
    s=s.replace('import { Link, useNavigate }','import { Link }')
      .replace('import { useState } from "react"','import { useState } from "react"\nimport LogoutButton from "./LogoutButton"')
      .replace(/  const navigate = useNavigate\(\)\n\n  const handleLogout = \(\) => \{[\s\S]*?\n  \}\n/, '')
      .replace(/<button\s+onClick=\{handleLogout\}[\s\S]*?<\/button>/g, '<LogoutButton />')
  } else {
    if(s.includes('fetch(')) {
      s=s.replace(/\bfetch\(/g,'apiFetch(')
        .replace(/^\s*const API_URL = import\.meta\.env\.VITE_API_URL;?\s*$/gm,'')
        .replaceAll('`${API_URL}/api/gad/','`${API_URL}/gad/')
        .replaceAll('`${API_URL}${imageUrl}`','`${ASSET_URL}${imageUrl}`')
        .replaceAll('`${API_URL}${service.image_url}`','`${ASSET_URL}${service.image_url}`')
        .replaceAll('`${API_URL}${formData.image_url}`','`${ASSET_URL}${formData.image_url}`')
        .replaceAll('`${API_URL}${item.image_url}`','`${ASSET_URL}${item.image_url}`')
      s='import { apiFetch, API_URL'+(s.includes('ASSET_URL')?', ASSET_URL':'')+' } from "../lib/api"\n'+s
    }
    if(name.endsWith('/AdminAccounts.jsx')) {
      s=s.replace('import { useEffect, useState } from "react"','import { useEffect, useState } from "react"\nimport { useAuth } from "../auth/AuthContext"')
        .replace('const currentUser = JSON.parse(localStorage.getItem("user"))','const { user: currentUser } = useAuth()')
        .replace('`${API_URL}/auth/register`','`${API_URL}/auth/users`')
        .replace('          currentUserRole: currentUser?.role,\n','')
        .replace('<option value="admin">Admin</option>','<option value="user">User</option>\n            <option value="admin">Admin</option>')
    }
  }
  return s
}
function putEnv(text, key, value, replace=false) {
  const rx=new RegExp('^'+key+'=.*$', 'm')
  if(rx.test(text)) return replace ? text.replace(rx,key+'='+value) : text
  return text.trimEnd()+'\n'+key+'='+value+'\n'
}
function main() {
  for(const name of ['package.json','client/src/App.jsx','server/server.js','server/db.js']) {
    if(read(name)===null) throw new Error('Open Command Prompt in the StyleSync project folder first. Missing: '+name)
  }
  const plan=new Map()
  const conflicts=[]
  const marker=read('.stylesync-login-fix-applied.json')
  const previous=marker ? JSON.parse(marker) : {}
  const panel=read('client/src/pages/AdminStaff.jsx')!==null
  for(const [name, item] of Object.entries(payload.files)) {
    const existing=read(name)
    if(item.optional && existing===null) continue
    if(item.onlyIfMissing && existing!==null) continue
    let next=item.content
    if(name==='client/src/App.jsx' && !panel) next=next.replace(/^import (AdminStaff|EmergencyMode).*\n/gm,'').replace(/^.*path="(staff|emergency)".*\n/gm,'')
    if(name==='server/server.js' && !panel) next=next.replace(/^  staff: require.*\n/gm,'')
    if(existing!==null && normalize(existing)!==normalize(next) && !item.before.includes(hash(existing)) && previous[name]!==hash(existing)) conflicts.push(name)
    if(existing===null || normalize(existing)!==normalize(next)) plan.set(name,next)
  }
  for(const [name, allowed] of Object.entries(payload.transforms)) {
    const existing=read(name)
    if(existing===null) continue
    if(previous[name]===hash(existing)) continue
    if(!allowed.includes(hash(existing))) { conflicts.push(name); continue }
    const next=transform(name,existing)
    if(normalize(existing)!==normalize(next)) plan.set(name,next)
  }
  if(conflicts.length) throw new Error('Stopped before changing any files. These files differ from the supplied source versions; keep your edits and ask for a tailored patch:\n'+conflicts.join('\n'))
  const pkg=JSON.parse(read('package.json'))
  pkg.dependencies={...pkg.dependencies,'express-session':'^1.19.0','express-mysql-session':'^3.0.3','express-rate-limit':'^8.7.0'}
  pkg.scripts={...pkg.scripts,start:'node server/server.js','migrate:auth':'node server/scripts/migrate-auth.js','test:auth':'node --test server/tests/auth.test.js'}
  plan.set('package.json',JSON.stringify(pkg,null,2)+'\n')
  let env=normalize(read('.env')||'')
  if(!/^SESSION_SECRET=.+$/m.test(env)) env=putEnv(env,'SESSION_SECRET',crypto.randomBytes(48).toString('hex'),true)
  env=putEnv(env,'NODE_ENV','development')
  env=putEnv(env,'PORT','5000')
  env=putEnv(env,'CLIENT_ORIGINS','http://localhost:5173,http://127.0.0.1:5173,http://localhost:5000,http://127.0.0.1:5000')
  env=putEnv(env,'TRUST_PROXY','0')
  plan.set('.env',env)
  plan.set('client/.env',putEnv(normalize(read('client/.env')||''),'VITE_API_URL','/api',true))
  const stamp=new Date().toISOString().replace(/[:.]/g,'-')
  const backup=path.join(root,'login-fix-backups',stamp)
  const manifest={created:[],replaced:[]}
  // Complete the backup before modifying any source file.
  for(const [name] of plan) {
    const target=path.join(root,name)
    if(fs.existsSync(target)) {
      const saved=path.join(backup,name); fs.mkdirSync(path.dirname(saved),{recursive:true}); fs.copyFileSync(target,saved)
      manifest.replaced.push(name)
    } else manifest.created.push(name)
  }
  fs.mkdirSync(backup,{recursive:true})
  fs.writeFileSync(path.join(backup,'manifest.json'),JSON.stringify(manifest,null,2))
  try {
    for(const [name,next] of plan) {
      const target=path.join(root,name); fs.mkdirSync(path.dirname(target),{recursive:true}); fs.writeFileSync(target,next)
    }
  } catch(error) {
    for(const name of manifest.replaced) fs.copyFileSync(path.join(backup,name),path.join(root,name))
    for(const name of manifest.created) fs.rmSync(path.join(root,name),{force:true})
    throw error
  }
  const hashes={...previous}
  for(const [name,next] of plan) if(!name.endsWith('.env')) hashes[name]=hash(next)
  fs.writeFileSync(path.join(root,'.stylesync-login-fix-applied.json'),JSON.stringify(hashes,null,2))
  console.log('Authentication changes applied. Existing modules and database credentials were preserved.')
  console.log('Backup: '+backup)
  console.log('Next: npm install')
  console.log('Then: npm install --prefix client')
  console.log('Back up your MySQL database, then: npm run migrate:auth')
  console.log('Start backend: npm start')
  console.log('In another terminal: npm run dev --prefix client')
  console.log('Open http://localhost:5173/. Read AUTHENTICATION_SETUP.md for details.')
  console.log('Keep the backup folder private; it may include your original environment settings.')
}
